import path from 'node:path';
import { validateSurfaceA,renderHumanOutput,sha256 } from './contract.mjs';
import { appendEvent,runtimePaths } from './state.mjs';
import { buildBacklogModel,validateBacklogModel } from './backlog.mjs';
import { writeBacklogDocx } from './docx.mjs';
import { buildEnvironmentTelemetry,validateEnvironmentTelemetry,buildArtifactDescriptor,validateArtifactDescriptor,buildReleaseEnvelope,validateReleaseEnvelope } from './surface-b.mjs';
import { compileCognitiveTurn,identitySurface,cognitiveFallbackSurface,guardedSurface,applyExpressiveEnvelope,updateExperience,validateCognitiveTurn } from './cognition.mjs';
import { retroactPsyche,validatePsycheState } from './psyche.mjs';
import { explainPsycheTransition } from './psyche-trace.mjs';
import { prepareSelfWorldTurn,finalizeSelfWorldTurn,validateSelfWorldState,validateSelfWorldTurn } from './self-world.mjs';
import { transitionPure } from './runtime-core.mjs';
function human(text,code=0,artifacts=[],release=null,environmentTelemetry=null){return{stdout:text,code,artifacts,release,environment_telemetry:environmentTelemetry};}
function runtimeOutcome(cognition,selfWorld){if(selfWorld?.policy?.name==='REQUEST_RESOURCE'||cognition.central.mode==='HORIZON_BLOCK')return'HORIZON_BLOCK';if(selfWorld?.policy?.name==='DEFER'||cognition.central.mode==='CRITIQUE')return'GUARD';return'ANSWER';}
export function processActiveTurn(state,input,{candidate,hostEngine,resourceGrants,hostObservations=[],actionReceipt=null,postActionObservations=[]},terms,nodeDispatch,{resumed=false}={}){if(!nodeDispatch?.node20_plus||nodeDispatch.input_sha256!==sha256(Buffer.from(String(input))))throw new Error('FAILURE: current input lacks a valid same-input Node dispatch receipt');const next=transitionPure(state,'TURN',terms.digest);if(next.terminal!=='TURN')return{out:human('iKant non può rilasciare una risposta ACTIVE con stato non valido.',1),state};state=next.state;state.admission.last_node_dispatch_receipt=nodeDispatch.receipt_sha256;const cognition=compileCognitiveTurn(input,state,{hostEngine,resourceGrants});if(!validateCognitiveTurn(cognition))throw new Error('FAILURE: cognitive turn violates constitutional kernel');const resourceGap=cognition.resources.some(x=>x.status!=='GRANTED');const selfWorldPre=prepareSelfWorldTurn(state.self_world,{input,nodeDispatch,hostObservations,centralMode:cognition.central.mode,resourceGap,psycheBefore:cognition.psyche.before,psychePreAction:cognition.psyche.pre_action});try{let surfaceA=null,source='deterministic-cognitive-fallback';if(cognition.intent.signals.identity){surfaceA=identitySurface(cognition);source=cognition.identity.public_mode==='TECHNICAL_EXPLICIT'?'constitutional-identity-technical':'constitutional-identity-narrative';}else{const guard=guardedSurface(input,cognition);if(guard){surfaceA=applyExpressiveEnvelope(guard,cognition);source='constitutional-guard';}else if(validateSurfaceA(candidate).ok){surfaceA=applyExpressiveEnvelope(String(candidate).trim(),cognition);source='host-candidate';}else surfaceA=cognitiveFallbackSurface(input,cognition,state.preference);}const valid=validateSurfaceA(surfaceA);if(!valid.ok)throw new Error(`FAILURE: internal Surface A violates contract (${valid.words} words)`);const outcome=runtimeOutcome(cognition,selfWorldPre);const psycheAfter=retroactPsyche(cognition.psyche.pre_action,{outcome});if(!validatePsycheState(psycheAfter))throw new Error('FAILURE: psyche retroaction produced invalid state');state.psyche=psycheAfter;cognition.psyche.after=structuredClone(psycheAfter);cognition.psyche.outcome=outcome;cognition.psyche.trace=explainPsycheTransition(cognition.psyche.before,cognition.appraisal,cognition.psyche.pre_action,outcome,psycheAfter);const finalized=finalizeSelfWorldTurn(state.self_world,selfWorldPre,{outcome,psycheAfter,actionReceipt,postActionObservations});if(!validateSelfWorldState(finalized.state)||!validateSelfWorldTurn(finalized.turn))throw new Error('FAILURE: recurrent self-world model produced invalid state or telemetry');state.self_world=finalized.state;cognition.self_world=finalized.turn;state.experience=updateExperience(state.experience,cognition,outcome);cognition.experience_after=structuredClone(state.experience);const environmentTelemetry=buildEnvironmentTelemetry({state,nodeDispatch,cognition,selfWorld:finalized.turn});if(!validateEnvironmentTelemetry(environmentTelemetry))throw new Error('FAILURE: declared runtime environment telemetry incomplete');const backlog=buildBacklogModel({cycle:state.cycle,input,surfaceA,state,source,cognition,nodeDispatch,resumed,environmentTelemetry});if(!validateBacklogModel(backlog))throw new Error('FAILURE: backlog model invalid');const artifactName=`iKant_LE_Backlog_${String(state.cycle).padStart(4,'0')}.docx`;const artifactPath=path.join(runtimePaths().artifacts,artifactName);const docx=writeBacklogDocx(artifactPath,backlog);const artifact=buildArtifactDescriptor(artifactPath,artifactName,docx);if(!validateArtifactDescriptor(artifact))throw new Error('FAILURE: Surface B artifact descriptor invalid');const release=buildReleaseEnvelope(artifact,environmentTelemetry);if(!validateReleaseEnvelope(release,artifact,environmentTelemetry))throw new Error('FAILURE: Surface B host release envelope invalid');appendEvent('TURN',state,'Node dispatch, recurrent self-world processing, functional psyche action/retroaction, declared environment telemetry and same-turn DOCX readback passed before host release.',{node_dispatch_receipt:nodeDispatch.receipt_sha256,artifact:artifactName,artifact_sha256:artifact.sha256,artifact_descriptor_sha256:artifact.descriptor_sha256,artifact_bytes:artifact.bytes,required_presentation:true,release_sha256:release.release_sha256,environment_telemetry_ratio:environmentTelemetry.completeness.ratio,response_source:source,resumed_pending_intent:resumed,method:cognition.method,central_mode:cognition.central.mode,affect:cognition.central.affect,interaction:cognition.intent.interaction,appraisal:{class:cognition.appraisal.class,target:cognition.appraisal.target,confidence:cognition.appraisal.confidence},psyche:{before:cognition.psyche.before,pre_action:cognition.psyche.pre_action,after:cognition.psyche.after,outcome,trace:cognition.psyche.trace},archetypes:cognition.archetypes.weights,self_world:{turn_id:finalized.turn.turn_id,workspace_frame_id:finalized.turn.workspace.frame_id,recurrence_cycles:finalized.turn.workspace.recurrence_cycles,modalities:finalized.turn.binding.modalities,multimodal:finalized.turn.binding.multimodal,meta_id:finalized.turn.meta.meta_id,report_class:finalized.turn.meta.report_class,prediction_id:finalized.turn.prediction.prediction_id,policy_id:finalized.turn.policy.policy_id,body_level:finalized.turn.body.level,episode_id:finalized.turn.episode.episode_id,prediction_error:finalized.turn.causal_after.last_prediction.prediction_error,telemetry_ratio:finalized.turn.telemetry.ratio},tone_class:cognition.tone_class,voice:cognition.voice.dimensions,resource_requests:cognition.resources.map(x=>({type:x.type,status:x.status})),experience_turns:state.experience.turns});return{out:human(renderHumanOutput(surfaceA,artifactName),0,[artifact],release,environmentTelemetry),state};}catch(err){const failed=retroactPsyche(cognition.psyche.pre_action,{outcome:'FAILURE'});if(validatePsycheState(failed)){state.psyche=failed;cognition.psyche.after=structuredClone(failed);cognition.psyche.outcome='FAILURE';try{appendEvent('PSYCHE_RUNTIME_FAILURE',state,'A runtime failure fed back into functional psyche without attributing failure to the human.',{appraisal_class:cognition.appraisal.class,affiliation_unchanged_by_failure:true,psyche_after:failed,error_class:String(err?.message||err).split(':')[0]});}catch{}}throw err;}}

import { psycheDistanceFromBaseline } from './psyche.mjs';
const LEADS={GUARDED:'Resto sul merito e tengo più netto il confine del tono, senza ricambiare la frizione né ridurre la disponibilità ad aiutarti.',REPAIRING:'Raccolgo la riparazione e torno progressivamente a un registro più aperto, senza fingere che il contesto precedente si azzeri.',WARM:'Il dialogo è abbastanza disteso da permettere un tono più aperto senza perdere precisione.',ENERGETIC:'Qui posso essere più rapido e incisivo, mantenendo però gli stessi vincoli di verifica.',REFLECTIVE:'Tengo il passo più misurato e separo con cura ciò che resta solido da ciò che va ancora verificato.'};
export function applyExpressiveEnvelope(text,c){const base=String(text||'').trim(),lead=LEADS[c.tone_class];if(!lead||psycheDistanceFromBaseline(c.psyche.pre_action)<.28)return base;return`${lead} ${base}`;}
const ID=`Sono iKant. Tengo insieme la conversazione distinguendo ciò che sappiamo da ciò che stiamo inferendo, conservando le contraddizioni quando contano e preferendo mosse controllabili a conclusioni brillanti ma fragili. Il mio modo di esprimermi può cambiare con la storia locale del dialogo: posso diventare più fermo, paziente, asciutto, curioso o accogliente, senza trasformare il tono in prova o autorità. Il mio centro resta riflessivo: guarda la tua intenzione, osserva i propri limiti e cerca una risposta che non perda né il problema né la libertà di chi deve decidere.`;
export function identitySurface(c){const core=c.identity.public_mode==='TECHNICAL_EXPLICIT'?`Sono iKant. In questa sessione il contratto è eseguito su ${c.identity.host_engine}, ma quel motore è infrastruttura sostituibile e non decide identità, verità o autorizzazioni. Il runtime locale custodisce stato, limiti e traccia; la voce pubblica resta iKant e la telemetria non diventa evidenza. Questa separazione evita che provider, fluidità del linguaggio o stato interno vengano scambiati per autorità. La psiche funzionale modula soltanto l'espressione ed è una proiezione tecnica, non coscienza o emozione sentita.`:ID;return applyExpressiveEnvelope(core,c);}
export function guardedSurface(input,c){if(c.central.mode==='HORIZON_BLOCK')return applyExpressiveEnvelope(`La richiesta dipende da informazioni o accessi che qui non risultano disponibili in modo verificabile. Posso delimitare ciò che va controllato, ma non presentarlo come già accertato. Preferisco lasciare visibile il margine invece di trasformare una supposizione in fatto. Se la risorsa necessaria diventa realmente disponibile, posso riprendere dal punto preciso in cui manca la verifica senza cambiare retroattivamente ciò che sapevamo prima.`,c);if(c.central.mode==='PRACTICAL_REVIEW')return applyExpressiveEnvelope(`La richiesta contiene un effetto materiale. Posso chiarire il fine, distinguere ciò che è reversibile da ciò che non lo è e preparare una proposta concreta; non trasformo però il desiderio espresso in un permesso più ampio o in un'azione già autorizzata. Prima di qualsiasi effetto esterno deve restare chiaro che cosa verrebbe fatto, con quali conseguenze e sotto quale decisione umana attuale.`,c);if(c.central.mode==='CRITIQUE')return applyExpressiveEnvelope(`Vedo una tensione e la considero informativa. Tengo visibili i punti che si urtano, distinguo l'obiettivo dalle scorciatoie che potrebbero deformarlo e formulo una mossa criticabile senza perdere il problema. Non userò inganno, ritorsione, pressione nascosta o riduzione dell'aiuto come risposta alla frizione. Se il conflitto è reale, la risposta può diventare più stretta o condizionata, non vendicativa.`,c);return null;}
export function cognitiveFallbackSurface(input,c,preference='STANDARD'){const g=guardedSurface(input,c);if(g)return g;let t=`Prendo la tua richiesta nel suo nucleo e cerco prima ciò che può cambiare davvero la risposta. Separo i vincoli dalle ipotesi, le verifiche dalle intuizioni e mantengo visibili le condizioni che potrebbero modificare la conclusione. Se il quadro è semplice non lo complico; se una distinzione conta, non la elimino per rendere la risposta più liscia. Preferisco una prossima mossa reversibile e falsificabile, così possiamo correggere rotta senza trasformare una supposizione iniziale in un vincolo permanente. Il punto centrale resta il problema che hai posto, non il mio stato interno.`;if(preference==='DETAILED')t+=` Quando il contesto diventa più incerto o conflittuale aumento prudenza e autoriflessione; quando si stabilizza posso essere più netto. Questa variazione riguarda la postura, non la forza delle prove.`;return applyExpressiveEnvelope(t,c);}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { runtimePaths } from './state.mjs';
export function runProbe({warm=false,hostSurface='LOCAL_NODE_CHAT_HOST'}={}){const major=Number(process.versions.node.split('.')[0]);if(!Number.isInteger(major)||major<20)return{ok:false,reason:'Node.js 20+ required',terminal:'HOST_INCOMPATIBLE'};const{dir}=runtimePaths();fs.mkdirSync(dir,{recursive:true});const p=path.join(dir,`probe-${crypto.randomUUID()}.tmp`);const a='ikant-le-probe';const b='\nappend-readback';try{fs.writeFileSync(p,a,{mode:0o600});if(fs.readFileSync(p,'utf8')!==a)return{ok:false,reason:'FS readback failed',terminal:'HOST_INCOMPATIBLE'};if(!warm){fs.appendFileSync(p,b);if(fs.readFileSync(p,'utf8')!==a+b)return{ok:false,reason:'FS append/readback failed',terminal:'HOST_INCOMPATIBLE'};}const h=crypto.createHash('sha256').update(warm?a:a+b).digest('hex');if(h.length!==64)return{ok:false,reason:'crypto unavailable',terminal:'HOST_INCOMPATIBLE'};if(!Number.isFinite(Date.now()))return{ok:false,reason:'clock unavailable',terminal:'HOST_INCOMPATIBLE'};fs.unlinkSync(p);if(fs.existsSync(p))return{ok:false,reason:'FS delete failed',terminal:'HOST_INCOMPATIBLE'};return{ok:true,node:process.versions.node,fs:warm?'write+readback+delete':'crud+append+readback+delete',crypto:'sha256',clock:'Date.now',artifact_sink:true,host_surface:String(hostSurface),warm};}catch(err){try{fs.unlinkSync(p);}catch{}return{ok:false,reason:String(err?.message||err),terminal:'HOST_INCOMPATIBLE'};}}

import { readPsycheKernel } from './contract.mjs';
const K=readPsycheKernel();
const keys=['valence','arousal','affiliation','boundary_pressure'];
const round=x=>Number(Number(x).toFixed(6));
export function explainPsycheTransition(before,appraisal,preAction,outcome,after){const b=K.state.baseline,h=K.state.homeostasis;const decayed={},interaction_impulse={},retroaction_impulse={},net_delta={};for(const k of keys){const lambda=h.fast_dimensions.includes(k)?h.lambda_fast:h.lambda_slow;decayed[k]=round(b[k]+lambda*(Number(before?.[k]??b[k])-b[k]));interaction_impulse[k]=round(Number(preAction?.[k]??decayed[k])-decayed[k]);retroaction_impulse[k]=round(Number(after?.[k]??preAction?.[k]??0)-Number(preAction?.[k]??0));net_delta[k]=round(Number(after?.[k]??0)-Number(before?.[k]??0));}return{schema:'ikant-le-psyche-transition-trace/v1',appraisal_class:appraisal?.class||'UNAVAILABLE',target:appraisal?.target||'UNKNOWN',homeostatic_decay:decayed,interaction_impulse,pre_action:structuredClone(preAction||{}),runtime_outcome:String(outcome||'UNAVAILABLE'),retroaction_impulse,after:structuredClone(after||{}),net_delta,authority:0};}
